verus! {
    pub fn is_sorted(arr: &Vec<i32>) -> (result: bool)
        requires
            arr.len() > 0,
        ensures
            result == (forall|i: int, j: int| 0 <= i < j < arr.len() ==> (arr[i] <= arr[j])),
    {
        // Initialize the result to true
        let mut res: bool = true;

        // Iterate through the array to check the sorting condition
        let n = arr.len();
        // We will check pairs (i, i+1) to ensure the array is sorted
        for i in 0..(n - 1) {
            // Check if the current element is greater than the next element
            if arr[i] > arr[i + 1] {
                // If we find any such pair, set res to false
                res = false;
                break; // No need to check further
            }
        }

        // Return the result
        res
    }
}